const A='/assets/';
const assets={hero:'hero-main-B6u4IPDm.jpg',tailor:'craftsmanship-D0trqJjg.jpg',atelier:'boutique-atelier-BX6aIiy-.jpg',shop:'boutique-storefront-DsTFcWEI.jpg',fabric:'boutique-fabrics-Cdr9fT36.jpg',wedding:'wedding-hero-Ce58TFcD.jpg',women:'women-suits-hero-BOfkQdXH.png',measure:'measurements-hero-BKGWc_a6.jpg'};
const products=[
 ['Charcoal Wool Suit','suit-charcoal-front-D8VzBoLA.png','Suits'],['Glen Plaid Double-Breasted','suit-glen-front-DmjC9ZfS.png','Suits'],['Cream Linen Suit','suit-cream-front-C1Nve6rn.png','Suits'],['Blue Hopsack Suit','suit-blue-front-iGSiV6W9.png','Suits'],
 ['Classic Navy Suit','men-suits-1-s-hMmhZu.jpg','Suits'],['Modern Grey Suit','men-suits-2-DMyieYPZ.jpg','Suits'],['Evening Black Suit','men-suits-3-CqykNgQ1.jpg','Suits'],['Contemporary Brown Suit','men-suits-4-B-prmpqK.jpg','Suits'],
 ['White Business Shirt','men-shirts-1-CppgV8tf.jpg','Shirts'],['Blue Cotton Shirt','men-shirts-2-LKHSWaqe.jpg','Shirts'],['Black Tie Tuxedo','men-tuxedos-1-DBdWgoob.jpg','Tuxedos'],['Satin Lapel Tuxedo','men-tuxedos-2-Dud5P7Z7.jpg','Tuxedos'],
 ['Tailored Jacket','men-jackets-1-ST2iy3tD.jpg','Jackets'],['Casual Blazer','men-jackets-2-B3Q_1M9p.jpg','Jackets'],['Women’s Power Suit','women-suit-1-Bjc_oU61.jpg','Women'],['Women’s Navy Suit','women-suit-2-OkB1O29x.webp','Women'],['Women’s Ivory Suit','women-suit-3-BA5SkpUj.jpg','Women'],['Bespoke Dress','women-dresses-1-CezltPxc.jpg','Women'],['Silk Blouse','women-blouses-1-D8ibKzDh.jpg','Women'],['Women’s Coat','women-coats-1-BgoOvt53.jpg','Women']
];
const img=n=>A+n;
const app=document.querySelector('#app');
function btn(h,t,c=''){return `<a href="${h}" class="btn ${c}" data-link>${t}</a>`}
function home(){return `<section class="hero" style="background-image:url('${img(assets.hero)}')"><div class="hero-copy"><span class="eyebrow">Bangkok's Atelier</span><h1>THE LEADING BESPOKE TAILOR</h1><p>Superior Service & Quality · World-class craftsmanship</p><div class="actions">${btn('/men/suits','Browse Suits','gold')}${btn('/contact','Book Appointment')}</div></div></section>
<section class="section"><div class="section-head"><span class="eyebrow">The Difference</span><h2 class="section-title">Custom Tailored vs Off the Rack</h2></div><div class="compare"><article><h3>Custom Tailored</h3><p>Made for you, only you.\n— Cut to your exact measurements for a flawless fit.\n— Choose every detail: fabric, lining, lapel, buttons and monogram.\n— Hand-finished construction built to age gracefully.\n— A silhouette that flatters your posture.</p></article><article><h3>Off the Rack</h3><p>Made for everyone, no one in particular.\n— Standard sizing makes fit a compromise.\n— Fabrics and styling are chosen by the brand.\n— Machine-made construction prioritises volume.\n— Rarely shaped to your individual frame.</p></article></div></section>
<section class="looks">${products.slice(0,4).map(p=>`<a class="look" href="/men/suits" data-link><img src="${img(p[1])}" alt="${p[0]}"><div class="caption"><span class="eyebrow">${p[2]}</span><h3>${p[0]}</h3><small>BROWSE SUITS</small></div></a>`).join('')}</section>
<section class="section alt"><div class="section-head"><span class="eyebrow">Design Your Own</span><h2 class="section-title">Choose Your Garment</h2><p>Endless customisation options. Every detail tailored to your exact measurements.</p></div><div class="categories">${[['SUITS','men-suits-1-s-hMmhZu.jpg','/men/suits'],['SHIRTS','men-shirts-1-CppgV8tf.jpg','/men/shirts'],['TUXEDOS','men-tuxedos-1-DBdWgoob.jpg','/men/tuxedos'],['WEDDING','category-wedding-DRNUCz3x.jpg','/wedding']].map(x=>`<a class="cat" href="${x[2]}" data-link><img src="${img(x[1])}" alt="${x[0]}"><h3>${x[0]}</h3><span class="eyebrow">View Collection</span></a>`).join('')}</div></section>
<section class="split"><img src="${img(assets.atelier)}" alt="Joe Suit atelier"><div class="split-copy"><span class="eyebrow">Since 2000 · Bangkok's Atelier</span><h2>A Legacy of Craftsmanship</h2><p>Joe Suit Tailor and Silk Custom Tailor is a Bangkok-based atelier producing high-quality bespoke clothing for over two decades. Every piece is handcrafted with precision at an honest price.</p><div class="stats"><div><strong>25+</strong><small>YEARS</small></div><div><strong>100+</strong><small>OPTIONS</small></div><div><strong>10K+</strong><small>CLIENTS</small></div></div><div class="actions" style="justify-content:flex-start">${btn('/about','Our Story','dark')}</div></div></section>
<section class="section"><div class="section-head"><span class="eyebrow">The Process</span><h2 class="section-title">How It Works</h2></div><div class="steps">${[['01','DESIGN','Choose your fabric, style, lapels, linings and finishing details.'],['02','MEASURE','Visit the atelier or follow our guided measurement process.'],['03','CRAFT','Master tailors hand-cut and assemble your garment.'],['04','RECEIVE','Collect in Bangkok or receive secure worldwide delivery.']].map(s=>`<div class="step"><b>${s[0]}</b><h3>${s[1]}</h3><p>${s[2]}</p></div>`).join('')}</div></section>
<section class="split"><div class="split-copy"><span class="eyebrow">Bespoke For Her</span><h2>Women's Clothing</h2><p>Suits, dresses, blouses and coats — meticulously tailored to celebrate your silhouette.</p><div class="actions" style="justify-content:flex-start">${btn('/women/suits','Browse Women’s Wear','dark')}</div></div><img src="${img(assets.women)}" alt="Women's bespoke tailoring"></section>
<section class="section world"><div class="section-head"><span class="eyebrow">Worldwide Delivery</span><h2 class="section-title">Tailored in Bangkok.<br>Delivered Globally.</h2><p>Secure, tracked, fully insured express delivery to over 200 countries.</p></div><div class="features"><div><h3>EXPRESS AIR</h3><p>DHL & FedEx door-to-door.</p></div><div><h3>FULLY INSURED</h3><p>Tracked end-to-end.</p></div><div><h3>FREE OVER USD 500</h3><p>On qualifying orders.</p></div></div><div class="actions">${btn('/contact','Get Shipping Quote','gold')}</div></section>
<section class="section alt"><div class="section-head"><span class="eyebrow">Excellent · 500+ reviews</span><h2 class="section-title">What Our Clients Say</h2></div><div class="reviews">${[['Srijana Gmr','Quality of fabric and final touch is really amazing.'],['Rigor Lois Alamar','A pleasant experience. Great service, craftsmanship and value.'],['S Tanoni','Professional guidance, great price and an excellent finished product.']].map(r=>`<article class="review"><div class="stars">★★★★★</div><p>${r[1]}</p><strong>${r[0]}</strong></article>`).join('')}</div></section>
<section class="section"><div class="section-head"><span class="eyebrow">The Journal</span><h2 class="section-title">Notes on Cloth & Craft</h2></div>${journalCards()}</section>`}
function journalCards(){return `<div class="journal-grid">${[['Your First Fitting: What to Expect',assets.tailor],['When to Dry Clean Your Suit',assets.fabric],['How to Choose a Wedding Suit',assets.wedding]].map(x=>`<article class="card"><img src="${img(x[1])}" alt=""><div class="card-body"><span class="eyebrow">The Journal · 4 min</span><h3>${x[0]}</h3><p>A concise guide from our Bangkok atelier.</p></div></article>`).join('')}</div>`}
function pageHero(title,sub,bg){return `<section class="page-hero" style="background-image:url('${img(bg)}')"><div class="inner"><span class="eyebrow">${sub}</span><h1>${title}</h1></div></section>`}
function catalog(gender,category){let title=category.replaceAll('-',' ').toUpperCase();let filtered=products.filter(p=>{if(gender==='women')return p[2]==='Women';return p[2].toLowerCase().includes(category.replace('pants','suit'))||category==='styles'});if(!filtered.length)filtered=gender==='women'?products.slice(14):products.slice(0,14);return `${pageHero(title,`${gender}'s collection`,gender==='women'?assets.women:'hero-tailor-OS_5BXdI.jpg')}<section class="section"><div class="section-head"><span class="eyebrow">Made To Measure</span><h2 class="section-title">${title}</h2><p>Browse signature silhouettes, then customise fabric, fit and finishing details with our tailors.</p></div><div class="product-grid">${filtered.map(p=>`<article class="card"><img loading="lazy" src="${img(p[1])}" alt="${p[0]}"><div class="card-body"><span class="eyebrow">${p[2]}</span><h3>${p[0]}</h3><a href="/contact" data-link>ENQUIRE →</a></div></article>`).join('')}</div></section>`}
function standard(path){const pages={
 '/about':['OUR STORY','Since 2000',assets.atelier,'For more than two decades, Joe Suit Tailor has created bespoke clothing for visitors and Bangkok residents. Our process combines careful consultation, precise measurement, hand-cut patterns and multiple fittings.','Crafted in Bangkok','Every garment is made by experienced tailors using carefully selected cloth, thoughtful construction and finishing that rewards close inspection.'],
 '/custom-made':['CUSTOM MADE','A garment of your own',assets.tailor,'Bespoke means starting with you: your measurements, posture, lifestyle and taste. Choose cloth, silhouette, lapels, pockets, lining, buttons and a personal monogram.','The Bespoke Process','Consultation, fabric selection, measurement, first fitting, refinement and final delivery — with each stage guided by our tailoring team.'],
 '/wedding':['WEDDING','Made for the moment',assets.wedding,'From the groom to the entire wedding party, we create coordinated formalwear that feels personal and photographs beautifully.','Wedding Appointments','Book early for unhurried fabric selection and fittings. Rush service may be available for Bangkok visitors.'],
 '/packages':['PACKAGES','Bespoke combinations',assets.fabric,'Choose a practical package for business, travel, weddings or a complete wardrobe refresh. Every item remains fully customisable.','Popular Packages','Essential: 1 suit + 2 shirts. Business: 2 suits + 4 shirts. Wedding: 1 tuxedo + 1 shirt + accessories. Contact us for current fabric options and pricing.'],
 '/gallery':['GALLERY','Selected work',assets.shop,'A closer look at tailored suits, tuxedos, jackets, shirts and womenswear made in our Bangkok atelier.','Recent Work',''],
 '/fabrics':['FABRICS','Cloth makes the character',assets.fabric,'Explore wool, linen, cotton, silk, cashmere blends and performance fabrics sourced for Bangkok weather and global wardrobes.','Choose by Purpose','Business, formal, wedding, travel and tropical-weight fabrics are available in hundreds of colours and patterns.'],
 '/journal':['THE JOURNAL','Cloth, craft and style',assets.tailor,'Notes from the atelier on choosing, wearing and caring for tailored clothing.','Latest Articles',''],
 '/faq':['FAQ','Before your visit',assets.shop,'Everything you need to know about appointments, fittings, timing, payments, alterations and shipping.','Frequently Asked Questions',''],
 '/measurements':['MEASUREMENTS','A precise fit begins here',assets.measure,'Visit our Bangkok atelier for the most accurate fitting, or use our guided diagrams when ordering remotely.','Self Measurement Guide',''],
 '/contact':['CONTACT','Visit or message us',assets.shop,'Platinum Fashion Mall, 222 Phetchaburi Rd, Ratchathewi, Bangkok. 3rd Floor, Zone 2, Soi Nathan-10, Room 908. Open daily 10am–8pm.','Book an Appointment','']};
 const p=pages[path]||pages['/about'];let body='';
 if(path==='/gallery')body=`<div class="gallery">${products.concat(products.slice(0,8)).map(p=>`<img loading="lazy" src="${img(p[1])}" alt="${p[0]}">`).join('')}</div>`;
 else if(path==='/journal')body=journalCards();
 else if(path==='/faq')body=`<div class="faq">${[['How long does a suit take?','Standard turnaround is usually 24–48 hours, depending on fabric, fittings and complexity.'],['Do I need an appointment?','Walk-ins are welcome, but an appointment helps us reserve fitting time for you.'],['Can you ship worldwide?','Yes. We provide tracked, insured express delivery to more than 200 countries.'],['Can you copy a favourite garment?','Yes, in many cases we can reproduce the fit and details while improving construction and fabric.'],['Do you tailor for women?','Yes. We make suits, blazers, trousers, blouses, dresses, skirts and coats.']].map(q=>`<details><summary>${q[0]}</summary><p>${q[1]}</p></details>`).join('')}</div>`;
 else if(path==='/measurements')body=`<div class="measure-grid"><img src="${img('measure-men-diagram-_LcHyY6J.jpg')}" alt="Men measurement guide"><img src="${img('measure-women-diagram-zf_pA9Gv.jpg')}" alt="Women measurement guide"></div>`;
 else if(path==='/contact')body=`<div class="contact-grid"><div><h3>Joe Suit Tailor</h3><p>Platinum Fashion Mall<br>3rd Floor, Zone 2, Soi Nathan-10, Room 908<br>Bangkok 10400</p><p><a href="tel:+66815544451">+66 81 554 4451</a><br><a href="https://wa.me/66815544451">Chat on WhatsApp</a></p></div><form class="form" id="contact-form"><input required placeholder="Your name"><input type="email" required placeholder="Email"><input placeholder="Phone / WhatsApp"><select><option>Book an appointment</option><option>Request a quote</option><option>Worldwide shipping</option></select><textarea placeholder="Tell us what you need"></textarea><button class="btn dark" type="submit">SEND ENQUIRY</button><div class="notice">Thank you. Please also message us on WhatsApp for the fastest reply.</div></form></div>`;
 else body=`<h2>${p[4]}</h2><p>${p[5]}</p><div class="actions" style="justify-content:flex-start">${btn('/contact','Book Appointment','dark')}</div>`;
 return `${pageHero(p[0],p[1],p[2])}<section class="section"><div class="content"><span class="eyebrow">Joe Suit Tailor · Bangkok</span><h2>${p[0]}</h2><p>${p[3]}</p>${body}</div></section>`}
function render(){const path=location.pathname.replace(/\/$/,'')||'/';if(path==='/')app.innerHTML=home();else if(/^\/(men|women)\//.test(path)){const [,g,c]=path.split('/');app.innerHTML=catalog(g,c)}else app.innerHTML=standard(path);bind();scrollTo(0,0)}
function bind(){document.querySelectorAll('[data-link]').forEach(a=>a.onclick=e=>{const u=new URL(a.href);if(u.origin===location.origin){e.preventDefault();history.pushState({},'',u.pathname);render();closeDrawer()}});const f=document.querySelector('#contact-form');if(f)f.onsubmit=e=>{e.preventDefault();f.querySelector('.notice').classList.add('show')}}
const drawer=document.querySelector('.drawer'),scrim=document.querySelector('.scrim');function closeDrawer(){drawer.classList.remove('open');scrim.classList.remove('show');document.body.classList.remove('no-scroll')};document.querySelector('.menu-btn').onclick=()=>{drawer.classList.add('open');scrim.classList.add('show');document.body.classList.add('no-scroll')};document.querySelector('.close-menu').onclick=closeDrawer;scrim.onclick=closeDrawer;addEventListener('popstate',render);render();
